import{_ as e,o,c as d,a2 as a}from"./chunks/framework.DTdEDYjJ.js";const n="/openbot/diagrams/bot-engine-last-mile-runtime.png",r="/openbot/diagrams/api-evolution-analysis.png",g=JSON.parse('{"title":"身份、执行与连接","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/architecture.md","filePath":"concepts/architecture.md"}'),s={name:"concepts/architecture.md"};function c(i,t,p,l,h,b){return o(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="身份、执行与连接" tabindex="-1">身份、执行与连接 <a class="header-anchor" href="#身份、执行与连接" aria-label="Permalink to &quot;身份、执行与连接&quot;">​</a></h1><p>OpenBot 持有 Bot 身份、持久状态与责任记录。模型服务、Harness、执行机器和屏幕后端分别适配，替换其中一个部分不应隐式改变权限。</p><h2 id="当前系统" tabindex="-1">当前系统 <a class="header-anchor" href="#当前系统" aria-label="Permalink to &quot;当前系统&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Mac App</span></span>
<span class="line"><span>  ├─ 对话与主脑</span></span>
<span class="line"><span>  ├─ 审批、进度、任务关系图</span></span>
<span class="line"><span>  └─ 代理任务与屏幕预览</span></span>
<span class="line"><span>           │ 显式执行连接</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>自建 Node</span></span>
<span class="line"><span>  ├─ 持久任务、取消与审计</span></span>
<span class="line"><span>  ├─ 每 Bot 模型 + DSH / Pi / legacy</span></span>
<span class="line"><span>  └─ 每 Bot 独立 Chromium 资料与输入队列</span></span></code></pre></div><p>Mac 和 Node 各自有安装身份。配置相同的 Bot ID 不代表对话、记忆、附件或凭据已经同步；当前跨主机派单依赖显式绑定与代理任务。</p><p>同一 OpenBot 内部使用宿主函数接口；客户端连接自己的 Node 使用现有 HTTP(S) JSON 接口。不同账号的独立 OpenBot 拟通过单独的 A2A Adapter 互通，该 Adapter 尚未实现。完整约定见 <a href="/openbot/concepts/bot-communication.html">Bot 协作与通信边界</a>。</p><h2 id="四个可替换部分" tabindex="-1">四个可替换部分 <a class="header-anchor" href="#四个可替换部分" aria-label="Permalink to &quot;四个可替换部分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部分</th><th>控制什么</th><th>当前实现</th></tr></thead><tbody><tr><td>模型服务</td><td>请求协议、凭据与实际模型</td><td>命名兼容 API 连接与现有网关</td></tr><tr><td>Harness</td><td>一次任务的模型和工具循环</td><td>默认DSH、显式Pi与legacy薄Adapter</td></tr><tr><td>执行机器</td><td>工具副作用发生的位置</td><td>Mac 本机或自建 Node</td></tr><tr><td>屏幕后端</td><td>画面、输入和接管</td><td>本机 Chromium 与 Node Playwright Chromium</td></tr></tbody></table><p>DSH、Pi与原有循环共用 OpenBot 的工具策略、审批、取消和动作账本。尚未适配的框架不会因为模型已接通就变为可用。</p><h2 id="常驻优先" tabindex="-1">常驻优先 <a class="header-anchor" href="#常驻优先" aria-label="Permalink to &quot;常驻优先&quot;">​</a></h2><p><strong>状态持久。</strong> Bot、任务与审计应活过重启。任务中断如实记录，不静默重跑。</p><p><strong>副作用记账。</strong> 工具动作关联执行者、任务、主机、屏幕和实际授权；缺少授权通道时不默认放行。</p><p><strong>可以中止。</strong> 取消与撤权要传递到正在执行的任务。拒绝后不换参数反复请求同一操作。</p><p>这些规则适用于一次任务结束之后。模型给出“已完成”文字，不替代宿主确认或实际观察证据。</p><h2 id="主脑与执行-bot" tabindex="-1">主脑与执行 Bot <a class="header-anchor" href="#主脑与执行-bot" aria-label="Permalink to &quot;主脑与执行 Bot&quot;">​</a></h2><p>主脑按职责拆解任务，向已配置的执行 Bot 派单。执行 Bot 使用自己的模型、Harness 和屏幕，主脑通过真实持久结果汇总。</p><p>贾维斯模式把组织折叠进一个对话，用户仍可展开任务、审批、用量与 Bot 箭头关系图。界面收起执行细节不减少授权要求。</p><h2 id="连接不等于同步" tabindex="-1">连接不等于同步 <a class="header-anchor" href="#连接不等于同步" aria-label="Permalink to &quot;连接不等于同步&quot;">​</a></h2><p>Node 使用自己的模型凭据与浏览器资料。客户端看到屏幕，不代表拿到了服务器文件系统或完整操作系统控制权。</p><p>当前是一个 Node 对一个执行控制客户端。断线使旧授权和旧输入失效，恢复连接后重新观察并显式交还。跨主机有限动作额度与页面完成条件暂不移交，相关主任务在入队前拒绝。</p><h2 id="hub-的边界" tabindex="-1">Hub 的边界 <a class="header-anchor" href="#hub-的边界" aria-label="Permalink to &quot;Hub 的边界&quot;">​</a></h2><p>独立预览Hub已用于设备配对和手机联调；日常App整合、统一账号和自动节点目录尚未交付。Node继续拥有执行和持久Bot状态，Hub与Node可部署在同一台主机。</p><p>云端 Bot 应以所属 Node 为状态来源，多端读取同一实体。账号相同不自动合并本地 Bot、不同节点的记忆或历史；数据迁移需要显式流程。</p><p>接口见 <a href="/openbot/reference/node-api.html">Node API</a>，执行框架见 <a href="/openbot/guide/harness.html">Harness 适配</a>。</p><h2 id="model-→-harness-→-botengine-runtime-架构提案" tabindex="-1">Model → Harness → BotEngine Runtime 架构提案 <a class="header-anchor" href="#model-→-harness-→-botengine-runtime-架构提案" aria-label="Permalink to &quot;Model → Harness → BotEngine Runtime 架构提案&quot;">​</a></h2><p>Bot Studio 的分层提案以模型提供推理、Harness 执行单次任务、Runtime 持有身份与任务状态为边界。S0 后台常驻和四窗口完整恢复仍在开发。已安装、隔离试验和公开接口的范围见<a href="/openbot/development/architecture-report.html">技术架构报告</a>。</p><ol><li><strong>Model 层（干线大脑与原子感知：<code>L1</code> / <code>L2</code>）</strong>：负责单次推理与标准化外部工具调用（如检索、网页抓取、OCR、ASR、TTS），本身无长期任务生命周期。</li><li><strong>Harness 层（单程执行脚手架：<code>L3</code>）</strong>：负责在单一工作目录内循环执行工具、改文件与跑测试（如 <code>dsh</code>、<code>agent:codex</code>、<code>kimi</code>）。单程脚本退出即停，无法独立承担跨入口身份、硬件权限仲裁或断点续履约。</li><li><strong>BotEngine Runtime 层（最后一公里操作系统：<code>L4</code>）</strong>：负责把前三层组织成常驻数字员工——持有 Bot 身份、固定执行器绑定（<code>D25</code>）、宿主密钥托管、Harvis 人工审批边界、异常/断电恢复（<code>4-window</code> / <code>unknown</code> 不重放）以及带 SHA-256 校验的 <code>openbot.task-receipt/1</code> 交付回执。</li></ol><p><img src="`+n+'" alt="BotEngine 最后一公里 Runtime 与三视角定位"></p><h3 id="最后一公里-last-mile-五维对照" tabindex="-1">最后一公里（Last-Mile）五维对照 <a class="header-anchor" href="#最后一公里-last-mile-五维对照" aria-label="Permalink to &quot;最后一公里（Last-Mile）五维对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>传统履约与外卖最后一公里难题</th><th>缺少 Runtime 时的 Agent 工程痛点</th><th>BotEngine（Bot Studio）工程解法</th></tr></thead><tbody><tr><td><strong>边际成本激增</strong></td><td>最后一公里分拣与投递占总成本最高比例</td><td>点个开关、刷个状态也重跑全量 L1/L3 循环</td><td>DSH <code>Workbench</code> 零模型调用动作（0-LLM）+ DeepSeek L2 工具 API 卸载感知查询</td></tr><tr><td><strong>最后 100 米寻址</strong></td><td>必须送到具体门牌与丰巢格口，而非城市分拨中心</td><td>混淆 <code>Bundle</code>/<code>Profile</code>/<code>Preset</code>，跨 Bot 上下文串联或猜目录</td><td>DSH 四层清晰边界 + 每 Bot <code>{}</code> 纯净目录配置 + <code>D25</code> 固定执行器隔离</td></tr><tr><td><strong>信任交接</strong></td><td>签收凭据、隐私脱敏与门槛核验</td><td>提示词泄露明文 API Key，未授权工具直接触碰宿主文件</td><td><code>preload.js</code> 零明文边界 + 宿主 <code>getApiKey</code> 注入 + Harvis 修订绑定审批</td></tr><tr><td><strong>异常与断电重投</strong></td><td>超时滞留、二次派送与签收确认</td><td>休眠、崩溃、离线直接丢任务或静默重放造成重复副作用</td><td><code>unknown</code> 永不静默重放 + 四窗口崩溃恢复 + 有界源端排队 + <code>openbot.task-receipt/1</code></td></tr><tr><td><strong>全渠道末梢触达</strong></td><td>统一库存同时履约 App、小程序与驿站</td><td>客户端需要逐个写专用插件才能调动后端数字员工</td><td>Bot as API / MCP / Anything（<code>published.chat@1</code> 供 Cherry Studio 等零插件直连）</td></tr></tbody></table><h2 id="ai-api-分层提案-l1-→-l4" tabindex="-1">AI API 分层提案（L1 → L4） <a class="header-anchor" href="#ai-api-分层提案-l1-→-l4" aria-label="Permalink to &quot;AI API 分层提案（L1 → L4）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>标准定义</th><th>调用单元</th><th>状态与身份</th><th>治理与审批</th><th>在 Bot Studio 中的协同方式</th></tr></thead><tbody><tr><td><strong>L1 大模型 API</strong></td><td>纯推理与生成接口</td><td>单次请求/响应（Token 流）</td><td>无状态</td><td>按账号/密钥计费与限流</td><td>每 Bot 可自由切换底层模型，可插拔替换</td></tr><tr><td><strong>L2 工具 API</strong></td><td>原子扩展能力接口（搜索、抓取、OCR、语音）</td><td>单次工具能力调用</td><td>无状态 / 轻量会话</td><td>宿主注钥、SSRF 拦截、密钥脱敏</td><td>作为加速器内嵌进 Bot 工作台与受控桥接，不与大模型本身绑定</td></tr><tr><td><strong>L3 Agent API</strong></td><td>单程工具编排与执行循环（Harness）</td><td>单次 Run / 会话循环</td><td>单次会话或独立 Worktree</td><td>沙箱 / 工具白名单</td><td>按固定执行器绑定（<code>dsh</code>、<code>agent:codex</code>、<code>kimi</code> 等），各展所长</td></tr><tr><td><strong>L4 Bot API</strong></td><td>面向结果的常驻数字员工接口（BotEngine）</td><td>任务派单 / <code>TaskReceipt</code> / 持续对话</td><td>持久身份、私人记忆与工作区</td><td>能力准入矩阵、Harvis 审批、SHA-256 交付证明</td><td>通过 <code>published.chat@1</code>（<code>GET /v1/models</code>、<code>POST /v1/chat/completions</code>）或跨 Bot 委派直接交付成果</td></tr></tbody></table><p><img src="'+r+'" alt="AI API 四层演进架构分析"></p><h2 id="三视角协同工作台-源码候选方向" tabindex="-1">三视角协同工作台（源码候选方向） <a class="header-anchor" href="#三视角协同工作台-源码候选方向" aria-label="Permalink to &quot;三视角协同工作台（源码候选方向）&quot;">​</a></h2><p>在隔离演进候选（<code>experiment-linked-workspace-perspectives</code> 与 <code>add-bot-capability-workbench</code>）中，桌面工作台通过 <code>BOT 视角</code>、<code>任务会话视角（C人工程视角）</code> 与 <code>文件交付视角</code> 将同一份后端真值映射为不同工作视图：</p><ul><li><strong>BOT 视角</strong>：围绕数字员工开展日常协作、IM/API 渠道接入与 Workbench 工作台零 LLM 快捷操作（带 <code>workbenchRevision</code> 乐观锁与 Harvis 确认）。</li><li><strong>任务会话（C人工程视角）</strong>：展示 <code>D25</code> 固定执行器身份、DSH 四层概念归类与 <code>D24</code> 五态能力真值（<code>installed</code> / <code>bound</code> / <code>activeInPlan</code> / <code>invoked</code> / <code>blocked</code>），直接呈现阻塞原因而不覆盖底层安装事实。</li><li><strong>文件交付视角</strong>：串联工作区产出文件、SHA-256 校验与 <code>openbot.task-receipt/1</code> 签收流水。</li></ul><p>进一步交互体验：<a href="./../bot-engine-runtime/index.html">打开 BotEngine Runtime 独立交互演示页</a>。</p>',37)])])}const m=e(s,[["render",c]]);export{g as __pageData,m as default};
